measurement_script:
import hashlib, json, statistics, subprocess, sys
from pathlib import Path
p = Path(sys.argv[1])
results = {"baseline": "9e12da277bc5a241783c253d29552d92a42a7553", "timing": [], "allocation": [], "binaries": {}, "conditions": {"cpu": "AMD Ryzen 5 5600G", "affinity": 0, "governor": "performance", "release_debug": 0, "release_incremental": False, "rust": "1.97.1", "iterations_small": 2000, "iterations_long": 200, "timing_warmup": 20, "timing_samples_per_process": 5, "timing_pairs": 7, "allocation_iterations": 10, "allocation_warmup": 2, "allocation_samples_per_process": 3, "allocation_pairs": 3}}
for rev in ["baseline", "fix"]:
    for mode in ["time", "alloc"]:
        binary = p / (rev + "-" + mode)
        results["binaries"][binary.name] = hashlib.sha256(binary.read_bytes()).hexdigest()
for mode, pairs in [("time", 7), ("alloc", 3)]:
    for case in ["marked", "control"]:
        for runs in [8, 512]:
            for pair in range(pairs):
                order = ["baseline", "fix"] if pair % 2 == 0 else ["fix", "baseline"]
                for revision in order:
                    iters = (2000 if runs == 8 else 200) if mode == "time" else 10
                    warmup, samples = (20, 5) if mode == "time" else (2, 3)
                    command = ["taskset", "-c", "0", str(p / (revision + "-" + mode)), case, str(runs), str(iters), str(warmup), str(samples)]
                    row = json.loads(subprocess.check_output(command))
                    row.update(revision=revision, pair=pair, order=order)
                    results["timing" if mode == "time" else "allocation"].append(row)
            print(mode, case, runs, "finished", flush=True)
summary = []
for case in ["marked", "control"]:
    for runs in [8, 512]:
        row = {"case":case,"runs":runs}
        digest = set()
        for revision in ["baseline", "fix"]:
            timings = [float(ns) / r["iterations"] for r in results["timing"] if r["case"]==case and r["runs"]==runs and r["revision"]==revision for ns in r["elapsed_ns"]]
            ar = [r for r in results["allocation"] if r["case"]==case and r["runs"]==runs and r["revision"]==revision]
            counts = [c for r in ar for c in r["allocations"]]
            assert len(timings)==35 and len(counts)==9
            assert all(c==counts[0] for c in counts)
            assert counts[0]["net_bytes"]==0
            alloc = {k:v/10 for k,v in counts[0].items() if k in ["allocated_bytes","alloc_calls","deallocated_bytes"]}
            alloc["peak_extra_bytes"] = counts[0]["peak_extra_bytes"]
            row[revision] = {"ns_per_line_median":statistics.median(timings), "ns_per_line_min":min(timings),"ns_per_line_max":max(timings), "allocation_per_line":alloc}
            digest.update(r["digest"] for r in results["timing"]+results["allocation"] if r["case"]==case and r["runs"]==runs and r["revision"]==revision)
        assert len(digest)==1
        row["digest"] = next(iter(digest))
        row["time_ratio"] = row["fix"]["ns_per_line_median"]/row["baseline"]["ns_per_line_median"]
        summary.append(row)
results["summary"] = summary
results["measurement_script"] = Path(__file__).read_text()
(p / "measurements.json").write_text(json.dumps(results,indent=2)+"\n")
print(json.dumps(summary,indent=2))
